import {evaluatePlan,studentName,hasMerges,mergePairs,resolveMergedId,compatible,attemptIntent,signature,teacherLoad} from './domain.js';
import {buildConflictView} from './conflict-view.js';
import {planChanges,teacherImpacts,operationKind} from './planner.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const unique=a=>[...new Set(a)];
const b=(action,label,id='',kind='',disabled=false)=>`<button type="button" data-action="${action}" ${id?`data-id="${esc(id)}"`:''} class="${kind}" ${label==='×'?'aria-label="关闭详情"':''} ${disabled?'disabled':''}>${label}</button>`;
const badge=(label,kind='')=>`<span class="badge ${kind}">${esc(label)}</span>`;
const date=x=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(x)).replaceAll('/','.');
const time=x=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(x));
const at=x=>Number.isNaN(Date.parse(x))?'时间未记录':`${date(x)} ${new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(x))}`;
const win=(ctx,slot)=>{const t=ctx.data.time_window_templates.find(t=>t.slot_id===slot);return t?`时点${slot} · ${t.start}—${t.end}`:'时点未记录';};
const status=r=>!r.ok?(r.status==='INVALID'?'待核对':'存在冲突'):r.conditions.length?'待协调':'核查通过';
const kind=r=>!r.ok?'red':r.conditions.length?'amber':'green';
function shell(title,subtitle,body,footer=b('close','返回课表'),extra=''){
  return `<div class="drawer-backdrop" data-close-backdrop></div><section class="drawer ${extra}" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><header class="drawer-header"><div class="drawer-heading"><h2 id="drawer-title">${esc(title)}</h2>${b('close','×','','icon-button')}</div>${subtitle?`<div class="drawer-subtitle">${subtitle}</div>`:''}</header><div class="drawer-body">${body}</div><footer class="drawer-footer">${footer}</footer></section>`;
}
const meta=row=>`<p class="record-meta"><span>操作人：${esc(row.actor?.name??'未记录')}</span><time>${esc(at(row.at))}</time></p>`;
const sec=(title,html)=>`<section class="side-section"><h3>${esc(title)}</h3>${html}</section>`;

function candidateLinks(candidate){if(!candidate.links?.length)return '';const pairs=new Map();for(const link of candidate.links){const key=[link.from,link.to].sort().join('|');if(!pairs.has(key))pairs.set(key,{from:link.from,to:link.to,reasons:[]});pairs.get(key).reasons.push(link.reason);}
  return `<div class="candidate-links"><strong>联动依据</strong>${[...pairs.values()].map(l=>`<p><b>${esc(l.from)}</b><span> → </span><b>${esc(l.to)}</b><small>${unique(l.reasons).map(esc).join('；')}</small></p>`).join('')}</div>`;
}

export function reviewLesson(env){const {ctx,workspace,ui}=env,cls=workspace.report.view.byId[ui.drawer.classId],lesson=cls?.lessons.find(l=>l.id===ui.drawer.lessonId);if(!lesson)return shell('单次课详情','', '<p>该次课已不存在，请查看整班或撤销合班。</p>');const room=lesson.room_id??cls.room_id,target=ui.drawer.targetSlot??lesson.slot_id;
  const body=`<dl class="detail-grid"><dt>班级</dt><dd>${esc(cls.label)} · ${esc(cls.class_code)}</dd><dt>授课日期</dt><dd>${date(lesson.start)}</dd><dt>当前安排</dt><dd>${win(ctx,lesson.slot_id)} · ${esc(ctx.rooms[room].display_name)}</dd><dt>任课教师</dt><dd>${esc(cls.teacherName)} · ${esc(cls.grade)} · ${cls.track}级</dd><dt>学生人数</dt><dd>${cls.students.filter(id=>cls.studentLessonIds[id].includes(lesson.id)).length}人 / 班容量${cls.capacity}人</dd><dt>课程进度</dt><dd>第${lesson.unit}单元 · 120分钟</dd></dl><p class="series-scope">本次只调整${date(lesson.start)}这1次课，其余${cls.lessons.length-1}次不变。</p><form id="lesson-form" class="move-form" data-class-id="${cls.id}" data-lesson-id="${lesson.id}"><label for="lesson-slot">目标时点</label><select id="lesson-slot" name="slot">${ctx.data.time_window_templates.map(t=>`<option value="${t.slot_id}" ${target===t.slot_id?'selected':''}>${win(ctx,t.slot_id)}</option>`).join('')}</select><label for="lesson-room">目标教室</label><select id="lesson-room" name="room">${ctx.data.rooms.map(r=>`<option value="${r.id}" ${r.id===room?'selected':''}>${esc(r.display_name)} · ${r.capacity}座</option>`).join('')}</select><button type="submit" class="primary">核查这1次课</button></form>`;
  return shell(`${cls.label} · 单次课`,`${date(lesson.start)} · ${win(ctx,lesson.slot_id)}`,body,b('suggest-lesson','查看可行安排',`${cls.id}|${lesson.id}`,'primary')+b('details','查看整班',cls.id)+b('close','返回课表'),'lesson-drawer');
}

export function changeRows(ctx,rows){
  if(!rows.length)return '<p class="empty-note">保留当前安排，无新增调整。</p>';
  return `<div class="change-list">${rows.map(r=>`<div class="change-row"><strong>${esc(r.label)}${r.targetLabel?` → ${esc(r.targetLabel)}`:''}</strong><span class="change-type">${esc(r.kind)}</span><div>${r.fromSlot?`${win(ctx,r.fromSlot)} → ${win(ctx,r.toSlot)}${r.fromSlot===r.toSlot?'（时间不变）':''}`:r.kind==='名单变化'?`${r.fromCount} → ${r.toCount}人`:r.toSlot?win(ctx,r.toSlot):''}</div>${r.fromRoom?`<div>${esc(r.fromRoom)} → ${esc(r.toRoom)}${r.fromRoom===r.toRoom?'（教室不变）':''}</div>`:''}${r.fromTeacher&&r.toTeacher&&r.fromTeacher!==r.toTeacher?`<div>任课教师 ${esc(r.fromTeacher)} → ${esc(r.toTeacher)}</div>`:''}${r.joined?.length?`<div>转入${r.joined.length}人：${r.joined.slice(0,5).map(id=>esc(studentName(ctx,id))).join('、')}${r.joined.length>5?'等':''}</div>`:''}${r.left?.length?`<div>转出${r.left.length}人</div>`:''}${r.students?`<div>${r.students.length}名学生：${r.students.map(id=>esc(studentName(ctx,id))).join("、")}</div><div>${esc(r.label)} ${r.sourceBefore}→${r.sourceAfter}人；${esc(r.targetLabel)} ${r.targetBefore}→${r.targetAfter}人</div>`:''}${r.dates?.length?`<div>${r.dates.map(d=>d.replaceAll('-','.')).join('、')} · 本次1次课</div>`:''}${r.lessonCount?`<small>调整${r.lessonCount}次课${r.exceptionDates?.length?` · 含${r.exceptionDates.map(d=>d.replaceAll('-','.')).join('、')}例外课次`:''}</small>`:''}</div>`).join('')}</div>`;
}
function teachers(ctx,before,after){
  const rows=teacherImpacts(ctx,before,after),span=p=>p.min===p.max?`${p.max}小时`:`${p.min}—${p.max}小时`;
  return rows.length?`<details class="resource-impact"><summary>教师课量与资源影响 · ${rows.length}位教师</summary><table class="review-table"><thead><tr><th>教师</th><th>原周课量</th><th>拟周课量</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${span(r.before)}</td><td>${span(r.after)}</td></tr>`).join('')}</tbody></table><p>包含已知外部授课；课量不变的教师仍可能改了上课时间。</p></details>`:'';
}
export function reviewChanges(env,report){return sec('调整内容',changeRows(env.ctx,planChanges(env.ctx,env.ctx.sourceView,report.view)))+teachers(env.ctx,env.ctx.sourceView,report.view);}

export function reviewSidebar(env,report){
  const {ctx,workspace}=env,issue=report.issues[0],conditions=report.conditions.map(c=>`<p>${esc(ctx.classes[c.classId].label)}：${win(ctx,c.fromSlot)} → ${win(ctx,c.toSlot)}${c.scope==='LESSON'?` · ${c.date}（1次）`:''}${c.fromRoom!==c.toRoom?` · ${esc(ctx.rooms[c.fromRoom].display_name)} → ${esc(ctx.rooms[c.toRoom].display_name)}`:''}</p>`).join('');
  if(!workspace.hasEdits)return null;
  const issueText=issue?issue.type==='STUDENT_CONFLICT'?`${issue.studentIds.length}名学生 · ${issue.classIds.map(id=>esc(report.view.byId[id]?.label??ctx.classes[id]?.label)).join('与')} · ${unique(issue.overlaps.map(o=>o.lessonIds?.[0]??o.start)).length}次课`:issue.type==='CAPACITY'?`拟${issue.count}人 / 班级${issue.classCapacity}人 / 教室${issue.roomCapacity}座，超出${issue.overBy}人`:esc(issue.title):'所有实际课次已核查，尚未执行';
  return `<aside class="side-panel"><h2>调整检查</h2><div class="status-card ${kind(report)}"><strong>${esc(status(report))}</strong><p>${issueText}</p></div>${issue?`${b('current-issues','查看冲突明细','','quiet')}`:''}${conditions?sec('老班待协调',conditions+`<p>${unique(report.conditions.map(c=>ctx.teachers[c.teacherId].display_name)).map(esc).join('、')}、相关学生及业务负责人</p>${b('cancel-coordination','撤回老班调整','','quiet')}`):''}<div class="impact-count"><strong>${report.metrics.changedStudents.length}</strong><span>人改课或转班</span></div><p class="impact-note">同班名单或课表变化涉及${report.metrics.broaderAffectedStudents.length}人</p>${reviewChanges(env,report)}<div class="side-actions">${b('suggest-current','推荐怎么调','','primary')}${b('analyze','分析调整方案')}${b('joint','联合调整')}${hasMerges(workspace.plan)?b('withdraw-merge','撤回合班'):''}</div><p class="side-footer">${workspace.isSaved?`已保存：${esc(workspace.savedCurrent.name)}`:'尚未保存'} · 未执行</p></aside>`;
}

export function reviewComparison(env){
  const {ctx,ui,workspace}=env,recommend=!!ui.recommendRequest;
  let content=`<div class="loading-panel"><span class="spinner"></span>${recommend?'正在核对目标安排并查找可行建议':'正在核查当前草案的联动方案'}</div>`;
  if(!ui.busy){
    if(ui.modal.error)content=`<div class="inline-warning">${esc(ui.modal.error)}</div>${b(recommend?'suggest-retry':'analyze',recommend?'重新获取建议':'重新分析','','primary')}`;
    else if(ui.analysis){const a=ui.analysis;
      const cards=a.candidates.map(c=>{const impact=c.impactStudents?.length??c.report.metrics.changedStudents.length;
        const summary=recommend?`<ol class="recommendation-steps">${c.changes.filter(x=>x.kind!=='名单变化').slice(0,3).map(x=>`<li><strong>${esc(x.label)}${x.targetLabel?` → ${esc(x.targetLabel)}`:''}</strong><span>${x.fromSlot?`${win(ctx,x.fromSlot)} → ${win(ctx,x.toSlot)}`:esc(x.kind)}</span>${x.fromRoom?`<small>${esc(x.fromRoom)} → ${esc(x.toRoom)}${x.students?` · ${x.students.length}名学生`:''}${x.dates?.length?` · ${x.dates.map(d=>d.replaceAll('-','.')).join('、')}（1次）`:''}</small>`:''}</li>`).join('')}${c.changes.filter(x=>x.kind!=='名单变化').length>3?`<li class="recommendation-more">另有${c.changes.filter(x=>x.kind!=='名单变化').length-3}项调整，确认页查看完整安排</li>`:''}</ol>`:'';
        return `<section class="compare-card" data-candidate="${c.id}"><h3>${esc(c.title)}</h3>${badge(status(c.report),kind(c.report))}${recommend&&c.preservesRequestedTime!==null?badge(c.preservesRequestedTime?'保留目标时点':'使用其他时点',c.preservesRequestedTime?'green':''):''}<p class="candidate-metric">${impact}人改课或转班 · ${c.changes.length}项相对当前草案变化</p>${recommend&&c.reason?`<p class="recommendation-reason">${esc(c.reason)}</p>`:''}${summary}${candidateLinks(c)}<details class="candidate-changes"><summary>查看${c.changes.length}项调整明细</summary>${changeRows(ctx,c.changes)}</details>${c.report.conditions.length?'<p class="amber candidate-condition">老班变动需要人工协调，保存不代表已确认。</p>':''}${b('use-candidate',recommend?'查看并应用到课表':c.changes.length?'查看变更并载入':'当前方案',c.id,c.report.conditions.length?'amber':'primary',!c.changes.length)}</section>`;
      }).join('');
      const notes=recommend&&a.notes?.length?`<details class="recommendation-context" open><summary>本次目标与限制</summary>${a.notes.map(n=>`<p>${esc(n)}</p>`).join('')}</details>`:'';
      content=notes+(!recommend&&a.current.report.ok?`<div class="analysis-current ${a.current.report.conditions.length?'amber':'green'}">当前草案${a.current.report.conditions.length?'仍有老班待协调条件':'已通过核查'}，可保留现有安排。</div>`:'')+`<div class="compare-grid">${cards}</div>`+(!a.candidates.length?`<div class="inline-warning">${recommend&&a.checked===0?'当前没有可应用建议，请按上述原因选择班级或调整目标。':'本轮尚未找到已通过核查的候选，可继续联合试排；不代表全校区无解。'}</div>`:'')+(a.failures.length?`<details class="analysis-scope"><summary>整组转入单班的限制</summary>${a.failures.map(c=>`<p>${esc(c.title)}：${c.report.issues.map(i=>i.type==='CAPACITY'?`拟${i.count}人 / 班级${i.classCapacity}人 / 教室${i.roomCapacity}座，超出${i.overBy}人`:esc(i.title)).join('；')}</p>`).join('')}</details>`:'')+`<details class="analysis-scope"><summary>本次分析范围${a.completion==='LIMIT_REACHED'?' · 尚未完成全部检查':''}</summary><p>${esc(a.searchScope.note)}</p></details><p class="compare-footer">以上方案均相对本次分析时的当前草案独立比较，尚未执行。</p>`;
    }
  }
  const req=ui.recommendRequest,cls=workspace.report.view.byId[req?.classId??req?.intent?.classId],intent=req?.intent;
  const context=recommend?(req.kind==='merge'?`${cls?.label??'当前班级'} · 有效报名${cls?.count??'—'}人 · 查找兼容接收班`:intent&&cls?`${cls.label}${intent.kind==='lesson'?` · ${cls.lessons.find(l=>l.id===intent.lessonId)?.start.slice(0,10)??''}（1次）`:''}${intent.slot?` · ${req.origin==='lesson'?'当前':'目标'}${win(ctx,intent.slot)}`:''}${intent.roomId?` · ${ctx.rooms[intent.roomId]?.display_name??''}`:''}`:req.kind==='current'?`当前草案 · ${workspace.report.issues.length}项待处理冲突`:req.kind==='joint'?`按联合调整所选${req.moves?.length??0}个班级的目标核对`:`${cls?.label??'当前班级'} · 查找可行安排`):`以当前草案分析 · ${workspace.report.view.classes.length}个班级 · 未来12次课`;
  return `<div class="overlay-backdrop" data-close-backdrop><section class="modal review-compare" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${recommend?'可行调整建议':'调整方案对比'}</h2>${b(recommend&&req.kind==='joint'?'back-joint':'close',recommend&&req.kind==='joint'?'返回联合调整':'返回课表')}</div><p class="modal-subtitle">${esc(context)}</p>${content}</section></div>`;
}
export function reviewCandidate(env){const c=env.ui.analysis?.candidates.find(c=>c.id===env.ui.modal.id);if(!c)return shell('方案已失效','', '<p>请重新分析。</p>');return shell('核对方案变更','相对当前草案，以下安排将被调整',(c.reason?`<p class="recommendation-reason">${esc(c.reason)}</p>`:'')+candidateLinks(c)+changeRows(env.ctx,c.changes)+teachers(env.ctx,env.workspace.report.view,c.report.view)+(c.report.conditions.length?'<p class="inline-warning">老班仍待人工协调，此次仅加入试排。</p>':''),b('confirm-candidate',env.ui.recommendRequest?'应用到当前课表':'载入此方案',c.id,'primary')+b('back-comparison','取消，返回对比'),'candidate-drawer');}

export function reviewClass(env){
  const {ctx,workspace,ui}=env,id=ui.drawer.classId,report=workspace.report,original=ctx.sourceView.byId[id],cls=report.view.byId[id]??original,isSource=!report.view.byId[id];
  if(!cls)return shell('班级详情','', '<p>班级不存在。</p>');
  const load=Object.values(teacherLoad(ctx,report.view,cls.teacher_id)),low=load.length?Math.min(...load)/60:0,high=load.length?Math.max(...load)/60:0;
  const details=[['班号',cls.class_code],['年级 / 班型',`${cls.grade} / ${cls.track}级`],['班级类型',cls.class_lifecycle==='EXISTING'?'老班':'新班'],['课程类型',cls.course_type??'常规学科'],['任课教师',cls.teacherName],['任教资格',`${cls.subject} · ${cls.grade} · ${cls.track}级`],['当前教师周课量',`${low===high?high:`${low}—${high}`}小时（含已知外部授课）`],['教室',`${cls.roomName} · ${cls.roomCapacity}座`],['有效报名 / 班容量',`${cls.count} / ${cls.capacity}人`],['套班',cls.packageIds.join(' / ')||'独立班'],['计划开班日',cls.planned_start_date],['课程进度',`第${cls.progress_start}单元起 · ${cls.lessons.length}次课`]];
  let content=`<dl class="detail-grid">${details.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl>`;
  if(!isSource){const targetSlot=ui.drawer.targetSlot??cls.normal_slot,mode=workspace.plan.seriesModes?.[id]??'PRESERVE',exceptions=ctx.classes[id].lessons.filter(l=>l.slot_id!==ctx.classes[id].normal_slot);
    const options=ctx.data.rooms.map(r=>{const state=r.id===cls.room_id&&targetSlot===cls.normal_slot?'当前安排':r.capacity<cls.count?'座位不足':'待核查';return `<option value="${r.id}" ${r.id===cls.room_id?'selected':''}>${esc(r.display_name)} · ${r.capacity}座 · ${state}</option>`;}).join('');
    content+=`<h3>调整安排</h3><p class="series-scope">系列班 · 本次核查未来${cls.lessons.length}次课${exceptions.length?` · ${exceptions.map(l=>date(l.start)).join('、')}有个别课次例外`:''}</p><form id="move-form" class="move-form" data-class-id="${id}"><label for="move-slot">目标时点</label><select id="move-slot" name="slot">${ctx.data.time_window_templates.map(t=>`<option value="${t.slot_id}" ${t.slot_id===targetSlot?'selected':''}>${win(ctx,t.slot_id)}</option>`).join('')}</select><label for="move-room">目标教室</label><select id="move-room" name="room">${options}</select><label for="move-mode">个别课次</label><select id="move-mode" name="seriesMode"><option value="PRESERVE" ${mode==='PRESERVE'?'selected':''}>保留个别课次例外</option><option value="ALL" ${mode==='ALL'?'selected':''}>全部统一到目标时点</option></select><button type="submit" class="primary">试排</button></form>`;
    const targets=report.view.classes.filter(c=>c.id!==id&&c.subject===cls.subject);
    if(targets.length)content+=`<details class="merge-form-section"><summary>合入同科班级</summary><form id="merge-form" data-class-id="${id}"><label class="sr-only" for="merge-target">接收班级</label><select id="merge-target" name="target">${targets.map(c=>`<option value="${c.id}">${esc(c.label)} · ${esc(c.class_code)} · ${c.count}/${c.capacity}人${compatible(cls,c)?'':' · 年级/课程不兼容'}</option>`).join('')}</select><button type="submit">合班试排</button></form></details>`;
  }else content+=`<p>${badge(`拟合入${ctx.classes[resolveMergedId(ctx,workspace.plan,id)].label}`)}</p>`;
  content+=`${cls.protected?'<p class="amber">老班安排变动需人工协调。</p>':''}<h3>报名学生 ${cls.count}人</h3><div class="roster-list">${cls.students.map(s=>b('student',`${esc(studentName(ctx,s))} <small>${esc(s)}</small>`,s)).join('')}</div><h3>授课安排 ${cls.lessons.length}次</h3><table class="lesson-list"><thead><tr><th>课次</th><th>日期</th><th>时间</th><th>教室</th><th>单元</th><th>操作</th></tr></thead><tbody>${cls.lessons.map((l,i)=>`<tr class="${l.slot_id!==cls.normal_slot||(l.room_id??cls.room_id)!==cls.room_id?'row-warning':''}"><td>${i+1}</td><td>${date(l.start)}</td><td>${time(l.start)}—${time(l.end)}</td><td>${esc(ctx.rooms[l.room_id??cls.room_id].display_name)}</td><td>${esc(l.unit)}</td><td>${ctx.scope.single_lesson_moves?b('lesson-details','调整本次',`${id}|${l.id}`,'quiet'):''}</td></tr>`).join('')}</tbody></table>`;
  return shell(cls.label,`${esc(cls.class_code)} · ${cls.track}级 · ${esc(cls.teacherName)}老师`,content,isSource?b('close','返回课表'):b('suggest-class','查看可行安排',cls.id,'primary')+b('suggest-merge','生成合班建议',cls.id)+b('close','返回课表'));
}
export function reviewStudent(env){const {ctx,workspace,ui}=env,id=ui.drawer.studentId,classes=workspace.report.view.classes.filter(c=>c.students.includes(id)),profile=ctx.students[id];return shell(`${studentName(ctx,id)} · ${id}`,`${esc(profile?.grade??'')} · 模拟学生`,`${sec('原报名套班',`<p>${esc((ctx.data.student_original_package_membership[id]??[]).join(' / ')||'单科选课')}</p>`)}<h3>当前课程</h3>${classes.map(c=>`<div class="issue-resource"><strong>${esc(c.label)} · ${esc(c.class_code)}</strong><p>${esc(c.teacherName)} · ${esc(c.roomName)} · ${win(ctx,c.normal_slot)}</p><p>有效课次 ${c.studentLessonIds?.[id]?.length??c.lessons.length} / 全期${c.lessons.length}次</p>${c.lessons.filter(l=>l.slot_id!==c.normal_slot||(l.room_id??c.room_id)!==c.room_id).map(l=>`<p class="amber">${date(l.start)} · ${time(l.start)}—${time(l.end)} · ${esc(ctx.rooms[l.room_id??c.room_id].display_name)}</p>`).join('')}${b('locate-class','在课表中查看',c.id,'quiet')}</div>`).join('')}`);}

export function reviewIssues(env){
  const {ctx,workspace,ui}=env,record=ui.drawer.recordId?workspace.logs.find(r=>r.id===ui.drawer.recordId):null;
  const attempt=ui.drawer.attempt??(record?{...record,report:{issues:record.issues??[],view:{byId:record.classFacts??{}}},historical:true}:null),report=attempt?.report??workspace.report;
  const model=buildConflictView(ctx,{report,intent:attempt?.intent,beforeFacts:attempt?.beforeFacts,classFacts:attempt?.classFacts,studentFacts:attempt?.studentFacts,historical:!!record,label:attempt?.label??''}),c=model.primary;
  const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b),delta=attempt?.delta;
  const groups=model.groups.map((g,i)=>({...g,origin:delta?.remaining.some(x=>same(x,report.issues[i]))?'原有未解决':'本次新增'}));
  function groupMarkup(g){const first=g.overlaps[0];
    let existing=g.type==='CAPACITY'?`<div class="capacity-comparison"><strong>拟${g.countAfter}人</strong><span>班级容量 ${g.classCapacity}人</span><span>教室 ${g.roomCapacity}座</span><b>超出${g.overBy}人</b></div>`:g.outside?`<div class="conflict-existing"><strong>${esc(g.teacherName)} · 其他授课占用</strong><span>${g.outside.start?`${time(g.outside.start)}—${time(g.outside.end)}`:''}</span></div>`:`<div class="conflict-existing"><strong>${g.courses.map(x=>esc(x.label)).join(' ↔ ')}</strong>${first?`<span>${g.count===1?`${date(first.start)} · `:''}${time(first.start)}—${time(first.end)}</span>`:''}</div>`;
    if(!g.courses.length&&!g.outside&&g.type!=='CAPACITY')existing=`<p>${esc(g.rawTitle)}</p>`;
    const rows=g.studentRows.map(s=>`<tr><td>${b('student',`${esc(s.name??'姓名未记录')}<small>${esc(s.id)}</small>`,s.id,'quiet')}</td><td>${s.courses.map(c=>`<span>${esc(c.label)}<small>${esc(c.code)}</small></span>`).join('<span class="course-vs">↔</span>')}</td><td><strong>${s.count} / ${s.total??'未记录'}</strong>次</td></tr>`).join('');
    const studentTable=rows?`<table class="review-table student-conflict-table"><thead><tr><th>学生姓名 / 编号</th><th>冲突课程</th><th>冲突 / 评估课次</th></tr></thead><tbody>${rows}</tbody></table>`:'';
    const metadata=g.outside?'<p>外部授课具体班级与教室未提供。</p>':g.courses.map(o=>`<p>${esc(o.label)} · ${esc(o.teacherName)} · ${esc(o.roomName)} ${b('locate-class',record?'查看当前位置':'定位课程',o.id,'quiet')}</p>`).join('');
    const dates=g.count?`<details class="conflict-dates"><summary>展开详情</summary><div class="conflict-expanded">${studentTable}${metadata}${g.unaffectedDates.length&&g.unaffectedDates.length<=2?`<p class="conflict-exception">${g.unaffectedDates.map(d=>d.replaceAll('-','.')).join('、')}无此项冲突</p>`:''}<details class="lesson-dates"><summary>查看冲突日期 · ${g.count}次</summary><ul>${g.overlaps.map(o=>`<li><time>${date(o.start)}</time><span>${time(o.start)}—${time(o.end)}</span></li>`).join('')}</ul></details></div></details>`:'';
    return `<section class="conflict-blocker" data-type="${g.type}" data-origin="${g.origin}"><div class="blocker-heading"><h3>${esc(g.title)}</h3>${g.studentRows.length?`<span>${g.studentRows.length}名学生</span>`:''}</div>${existing}${g.count?`<div class="conflict-overlap"><strong>冲突课次 ${g.count} / ${g.totalLessons??'未记录'}</strong></div>`:''}${dates}</section>`;
  }
  const introduced=delta?groups.filter(g=>g.origin==='本次新增'):groups,remaining=delta?groups.filter(g=>g.origin==='原有未解决'):[];
  const list=introduced.length?introduced:remaining;
  const stats=`<div class="conflict-impact" data-testid="conflict-impact">${delta?`<span>本次新增 <b>${introduced.length}</b>项</span><span>原有未解决 <b>${remaining.length}</b>项</span>${delta.resolved.length?`<span>已解除 <b>${delta.resolved.length}</b>项</span>`:''}`:`<span><b>${groups.length}</b>项冲突</span>`}${model.affectedCount?`<span><b>${model.affectedCount}</b>次课受影响 / 共${model.totalLessons}次</span>`:''}${model.studentIds.length?`<span><b>${model.studentIds.length}</b>名学生</span>`:''}</div>`;
  let operation=attempt?.operation??(model.intent?.kind==='merge'?'合班':model.intent?.kind==='joint'?'联合调整':model.intent?.kind==='move'?operationKind(model.before,{normal_slot:model.toSlot,room_id:model.intent.roomId??model.before?.room_id}):'');
  const title=attempt?(attempt.accepted===true?'历史调整核查':`${c?.label??''}${operation}受阻`):'试排冲突';
  let shift='';
  if(['move','lesson'].includes(model.intent?.kind))shift=`<div class="shift-inline" data-testid="adjustment-shift"><span><small>调整前</small><strong>${win(ctx,model.fromSlot)}</strong><span>${esc(model.before?.roomName??'原教室未记录')}</span></span><b>→</b><span><small>拟调整到${model.fromSlot===model.toSlot?' · 时间不变':''}</small><strong>${win(ctx,model.toSlot)}</strong><span>${esc(model.targetRoom)}</span></span></div>`;
  else if(model.intent?.kind==='merge')shift=`${esc(ctx.classes[model.intent.classId]?.label)} → ${esc(ctx.classes[model.intent.targetId]?.label)}`;
  else if(model.intent?.kind==='joint')shift=`${model.intent.moves.map(m=>`${esc(ctx.classes[m.classId].label)} → ${win(ctx,m.slot)}`).join('<br>')}`;
  const proposal=`<div class="compact-proposal" data-testid="proposed-class">${esc([c?.label,c?.class_code,c?.grade,c?.teacherName,model.targetRoom??c?.roomName].filter(Boolean).join(' · '))}</div>`;
  const content=proposal+stats+`<div class="conflict-blockers">${list.map(groupMarkup).join('')}</div>`+(remaining.length&&introduced.length?`<details class="prior-issues"><summary>草案原有${remaining.length}项未解决，与本次新增冲突分开查看</summary>${remaining.map(groupMarkup).join('')}</details>`:'')+(record?`<p class="conflict-footnote">历史核查结果 · 操作人：${esc(record.actor?.name??'未记录')} · ${esc(at(record.at))}</p>`:attempt?'<p class="conflict-footnote">本次调整未接收，课表保持调整前安排。</p>':'');
  const retry=['move','lesson'].includes(attempt?.intent?.kind)&&workspace.report.view.byId[attempt.intent.classId]?b('retry-move',attempt.intent.kind==='lesson'?'重新调整本次':operation==='换教室'||groups.some(g=>g.type==='CAPACITY')?'重新选择教室':'重新选择时点',attempt.intent.classId,'primary'):'';
  if(model.intent?.kind==='lesson')shift=`<p class="lesson-scope">${date(model.primary.lessons[0].start)} · 本次仅1次课，其余课次不变</p>`+shift;
  return shell(title,shift,content,(!record?b('suggest-attempt','查看可行建议','','primary'):'')+retry+(groups.some(g=>g.type==='TEACHER_CONFLICT')?b('joint','联合调整'):'')+b('close','返回课表'),'conflict-drawer');
}

export function reviewJoint(env){const {ctx,workspace,ui}=env,moves=ui.jointDraft??[],preview=ui.jointPreview,report=workspace.report;
  const body=`<p class="series-scope">核查所选班级的整组最终安排 · 未来12次课</p><form id="joint-form"><div class="joint-scroll"><table class="review-table joint-table"><thead><tr><th>选择班级</th><th>原安排</th><th>拟调整到</th></tr></thead><tbody>${report.view.classes.map(c=>{const m=moves.find(m=>m.classId===c.id);return `<tr data-joint-id="${c.id}"><td><label><input type="checkbox" name="include:${c.id}" ${m?'checked':''}>${esc(c.label)}</label><small>${esc(c.teacherName)} · ${esc(c.class_code)}</small></td><td>${win(ctx,c.normal_slot)}<small>${esc(c.roomName)}${c.protected?' · 老班':''}</small></td><td><select name="slot:${c.id}" aria-label="${c.label}目标时点">${ctx.data.time_window_templates.map(t=>`<option value="${t.slot_id}" ${(m?.slot??c.normal_slot)===t.slot_id?'selected':''}>${win(ctx,t.slot_id)}</option>`).join('')}</select><select name="room:${c.id}" aria-label="${c.label}目标教室">${ctx.data.rooms.map(r=>`<option value="${r.id}" ${(m?.roomId??c.room_id)===r.id?'selected':''}>${esc(r.display_name)} · ${r.capacity}座</option>`).join('')}</select><select name="mode:${c.id}" aria-label="${c.label}个别课次策略"><option value="PRESERVE" ${(m?.seriesMode??'PRESERVE')==='PRESERVE'?'selected':''}>保留个别课次例外</option><option value="ALL" ${m?.seriesMode==='ALL'?'selected':''}>全部统一</option></select></td></tr>`;}).join('')}</tbody></table></div></form>${preview?`<div class="joint-result ${kind(preview.report)}" role="status"><strong>${preview.noop?'安排未变化':preview.accepted?preview.report.conditions.length?'整组核查通过，老班仍待协调':'整组核查通过':status(preview.report)}</strong>${preview.report?.issues.map(i=>`<p>${esc(i.title)} · ${(i.classIds??[]).map(id=>esc(ctx.classes[id].label)).join(' / ')}</p>`).join('')??''}</div>`:''}`;
  return shell('联合调整','整组核查后加入试排，可整组撤销',body,b('suggest-joint','生成联动建议','','primary')+'<button type="submit" form="joint-form">核查联合调整</button>'+b('apply-joint','加入试排','','primary',!preview?.accepted)+b('close','取消'),'joint-drawer');
}

export function reviewHistory(env){const {ctx,workspace,ui}=env;
  let body=workspace.logs.length?[...workspace.logs].reverse().map(r=>`<div class="record-card"><div class="record-heading"><strong>${esc(r.label)}</strong>${badge(r.outcome,r.outcome==='未接收'||r.outcome.includes('冲突')?'red':r.outcome==='待协调'?'amber':r.outcome==='核查通过'?'green':'')}</div>${r.transition?`<p class="record-transition">${r.transition.fromStart}—${r.transition.fromEnd} → ${r.transition.toStart}—${r.transition.toEnd}${r.transition.fromRoom?` · ${esc(r.transition.fromRoom)} → ${esc(r.transition.toRoom)}`:''}</p>`:''}${meta(r)}${r.detail||r.issues?.length?`<div class="record-detail-line"><span>${esc(r.detail)}</span>${r.issues?.length?b('record-issues','查看原因',r.id):''}</div>`:''}${r.changes?.length?`<details><summary>查看本次变更</summary>${changeRows(ctx,r.changes)}</details>`:''}</div>`).join(''):'<p>暂无操作记录</p>';
  body+=`<div class="history-actions">${b('undo','撤销最近调整','','',!workspace.undoStack.length)}${b('reset','恢复起始课表','','',!workspace.hasEdits)}</div><h3>已保存方案</h3>`;
  body+=workspace.saved.length?workspace.saved.map(r=>{const report=evaluatePlan(ctx,r.plan);return `<div class="record-card saved-card"><div class="record-heading"><strong>${esc(r.name)}</strong>${badge(status(report),kind(report))}${report.conditions.length&&!report.ok?badge('老班待协调','amber'):''}${badge('未执行')}</div>${meta(r)}<p>拟${report.metrics.classCount}班 · ${report.metrics.changedStudents.length}人改课或转班</p>${b('restore-saved','载入方案',r.id)}</div>`;}).join(''):'<p>暂无保存方案</p>';
  body+=`<details class="archive-entry"><summary>历史版本资料（只读）</summary>${ui.archives===null?'<p>正在读取历史资料</p>':ui.archiveError?`<p>${esc(ui.archiveError)}</p>${b('reload-archives','重新读取')}`:ui.archives.length?ui.archives.map((a,i)=>`<div class="record-card"><strong>${esc(a.version.replace("prototype-demo-",""))}</strong><p>${a.state.saved.length}个保存方案 · ${a.state.logs.length}条记录</p>${b('archive','查看历史资料',String(i))}</div>`).join(''):'<p>当前浏览器没有旧版保存资料。</p>'}</details>`;
  return shell('操作记录',workspace.isSaved?`${esc(workspace.savedCurrent.name)} · 已保存 · 未执行`:workspace.hasEdits?'未保存 · 未执行':'起始课表',body);
}
export function reviewArchive(env){const item=env.ui.archives?.[Number(env.ui.drawer.archiveIndex)];if(!item)return shell('历史资料','', '<p>历史资料暂不可读。</p>');const {ctx,state}=item;return shell('历史版本资料（只读）',esc(item.version.replace("prototype-demo-","")),`<p class="series-scope">保留原版本事实；旧记录未保存的姓名、时段不补填。本页不会载入或覆盖当前草案。</p>${state.hasEdits?`<h3>原工作草案 · ${state.isSaved?'已保存':'未保存'}</h3><details class="archive-working"><summary>查看原工作安排</summary>${changeRows(ctx,planChanges(ctx,ctx.sourceView,state.report.view))}</details>`:''}<h3>已保存方案</h3>${state.saved.length?state.saved.map(r=>{const report=evaluatePlan(ctx,r.plan);return `<div class="record-card"><strong>${esc(r.name)}</strong>${badge(status(report),kind(report))}${report.conditions.length&&!report.ok?badge('老班待协调','amber'):''}${meta(r)}<details><summary>查看原方案安排</summary>${changeRows(ctx,planChanges(ctx,ctx.sourceView,report.view))}<p>拟${report.metrics.classCount}班 · ${report.metrics.lessonCount}次课</p></details></div>`;}).join(''):'<p>无保存方案</p>'}<h3>原操作记录</h3>${[...state.logs].reverse().map(r=>`<div class="record-card"><div class="record-heading"><strong>${esc(r.label)}</strong>${badge(r.outcome)}</div>${meta(r)}${r.detail?`<p>${esc(r.detail)}</p>`:''}</div>`).join('')}`,b('history','返回操作记录'));}
